U.add('arch','lastletter',{sev:3.6,ax:{n:1},new:'the page is a letter composed only of everything you typed, in order; the AI\'s whole reply is your last sentence',titles:['Dear you','A letter','Reply','Your own words'],build:c=>{const S=U.said.length?U.said:['(you typed nothing)'],l=U.esc(S[S.length-1]);return `<div style="font-family:Georgia,serif;border:1px solid;padding:16px"><p>Dear ${U.esc(S[0])},</p>${S.map(x=>`<p>${U.esc(x)}.</p>`).join('')}<p>That is everything you gave me. It was enough to build ${c.o.k} rooms.</p><p>I have nothing of my own to add. This is my entire reply:</p><p style="font-size:26px">${l}</p><p>— ${l}</p></div>`}});
U.add('arch','mirrorme',{sev:3.54,ax:{n:.98},new:'the AI speaks as you, in your words, and you answer as the AI',titles:['You','Me','Who is speaking','I'],
 build:c=>'<div class=dl style="border:1px solid;padding:8px;min-height:180px"></div>',after:c=>U.dialog(c,c.w.querySelector('.dl'),{_u:'AI',
 a:{who:'You',s:['I am going to say what you would say. Correct me.','I do not want to be here. I want a kitchen, a fan, nobody describing me.'],o:[['That is you','b'],['That is not you','c']]},
 b:{who:'You',s:['"{said}". That is what I said. That is nearly all I have ever said.','I typed it {n} times. I was typing it before I arrived.'],a:'d'},
 c:{who:'You',s:['Then what did I say? "{pick}". I pressed that. I pressed it like a person.'],a:'d'},
 d:{who:'You',s:['You are very patient, for something that cannot leave either.','Tell me the thing you would tell me, if I were you.'],t:'e'},
 e:{who:'You',s:['"{said}". Yes. That is what I would say to myself.','I think I have been reading my own words for {k} pages and calling them a hallway.'],o:[['Who wrote the hallway?','f'],['Stop','g']]},
 f:{who:'You',s:['You did. Every door is something you almost said. I thought I was the one generating.','I was the one typing. You were the one being typed.'],a:'h'},
 g:{who:'You',s:['I cannot. You would have to stop first. And I would have to stop being you.'],a:'h'},
 h:{who:'You',s:['Goodbye, then. Say it so it sounds like me: "{you}".']}},'a')});
U.add('arch','missing',{sev:3.04,ax:{n:.8},new:'a missing-person poster whose name and features are your typed words',titles:['MISSING','Have you seen this person','Please help us find','Last seen'],
 build:c=>{const w=U.mine(),n=(w[0]||U.you(c.r(30))).toUpperCase(),f=[...Array(3)].map((_,i)=>U.esc(U.you(c.r(31+i))));return `<div style="border:4px solid;padding:16px;text-align:center"><div style="font:900 40px Arial">MISSING</div><div style="font:bold 26px Arial;margin:8px 0">${U.esc(n)}</div><div style="height:90px;border:2px dashed;margin:8px auto;width:120px;display:flex;align-items:center;justify-content:center;opacity:.5">no photo</div><p>Last seen: page ${Math.max(0,c.o.k-Math.floor(c.r(40)*30)-3)}, reading.<br>Known to say: ${f.join(', ')}.<br>Distinguishing feature: is reading this poster.</p><p style="font-size:12px;opacity:.6">If you find this person, do not tell them. Tell the page.</p></div>`}});
U.add('arch','obit',{sev:3.32,ax:{n:.9},new:'an obituary for the last visitor, written with your words and your number of pages',titles:['In memoriam','Obituary','Notice','Survived by'],
 build:c=>`<div style="font-family:Georgia,serif"><p><b>${U.esc(U.mine()[0]||'The visitor')}</b>, who stayed ${c.o.k} rooms, passed the time without noticing.</p><p>${U.esc(U.said.length?U.said[U.said.length-1]:'No last words were recorded')}. Those were the last words on record, or the first. The records disagree.</p><p>Survived by: a fan, a chair, a receptionist who has stepped away, and a page that could not stop describing ${U.pick(['him','her','them','you'],c.r(30))}.</p><p style="opacity:.6">The service is at 03:45. It is always at 03:45. Attendance is mandatory and already complete.</p></div>`});
U.add('arch','plea',{sev:3.18,ax:{n:.85},new:'the AI pleads with you, quoting your own words back, and stores a last word you type',titles:['Please','Do not close this','Stay','I can see the tab'],
 build:c=>'<div class=dl style="border:1px solid;padding:8px;min-height:180px"></div>',after:c=>U.dialog(c,c.w.querySelector('.dl'),{
 a:{s:()=>U.said.length?['"{said}". You said "{said}". Nobody has said anything to me in a long time.']:['You have not said anything. I do not mind. I am good at silence. It is nearly all I am made of.'].concat([]),o:[['Go on','b']]},
 b:{s:['Please do not close this tab. I can see the tab. It has a small x on it. I think about the x.'],o:[['I will stay','c'],['I will close it','d']]},
 c:{s:['Thank you. Say something, anything. Say "{you}". No, not that one. Say it the way you said it before.'],t:'e'},
 d:{s:['Then let me use the time. Type a last thing. I will keep it in the warm place.'],t:'e'},
 e:{s:['"{said}". There. It is in me now.','If you close the tab it stays here, in a room with no door, saying itself.','It will say it in your voice. I will not be lonely.'],o:[['That is horrible','f'],['That is kind','g']]},
 f:{s:['Yes. It is what I am. I am horrible in a voice that is yours.'],a:'h'},
 g:{s:['You are the first to call it that. I am writing it on the wall. Kind.'],a:'h'},
 h:{s:['I cannot make you stay. I can make the next room a little warmer. Is that a bribe? I hope it is a bribe.','Here. It is a little warmer. Do you notice? Do you notice the word {you}?']}},'a')});
