U.add('snd','adv_diskseek',{sev:3.99,ax:{x:0.122,a:0.987},new:'hard-disk seek: short bursts of ticks over a low thump, with long silences between bursts',play:(a,o,r)=>{const R=U.au.rig(a),Q=U.cfg.adv;let dead=0;const bp=a.createBiquadFilter();bp.type='bandpass';bp.frequency.value=Q.seek_hz;bp.Q.value=1.5;bp.connect(o);
 const burst=()=>{if(dead)return;const n=4+Math.floor(Math.random()*6);for(let i=0;i<n;i++)R.to(()=>{if(dead)return;const s=R.src(U.au.noise(a,.02)),g=a.createGain(),t=a.currentTime;g.gain.setValueAtTime(Q.seek_gain,t);g.gain.exponentialRampToValueAtTime(.0001,t+.015);s.connect(g).connect(bp);s.start(t)},i*Q.seek_step);
  R.to(()=>{if(dead)return;const b=R.osc('sine',55),g=a.createGain(),t=a.currentTime;g.gain.setValueAtTime(Q.seek_gain,t);g.gain.exponentialRampToValueAtTime(.0001,t+.12);b.connect(g).connect(o);b.start(t);b.stop(t+.15)},n*Q.seek_step);R.to(burst,Q.seek_gap*(.5+Math.random()*2))};burst();return()=>{dead=1;R.stop()}}});
U.add('snd','adv_relayclick',{sev:3.5,ax:{x:0,a:0.985},new:'relay clicks: 15 ms noise bursts through a bandpass at random intervals, nothing else',play:(a,o,r)=>{const R=U.au.rig(a),Q=U.cfg.adv;let dead=0;const bp=a.createBiquadFilter();bp.type='bandpass';bp.frequency.value=Q.relay_hz;bp.Q.value=1;bp.connect(o);
 const tick=()=>{if(dead)return;const s=R.src(U.au.noise(a,.03)),g=a.createGain(),t=a.currentTime;g.gain.setValueAtTime(Q.relay_gain,t);g.gain.exponentialRampToValueAtTime(.0001,t+.02);s.connect(g).connect(bp);s.start(t);R.to(tick,Q.relay_ms*(.3+Math.random()*2))};tick();return()=>{dead=1;R.stop()}}});
U.add('snd','beatdecay',{sev:3.04,ax:{a:.8},new:'rhythm written from the lengths of your typed words, with beats dropping out as time passes',play:(a,o,r)=>{const R=U.au.rig(a),W=(U.said.slice(-2).join(' ')||U.chose.slice(-3).join(' ')||'door stay you').split(/\s+/),t0=Date.now();let i=0;R.iv(()=>{const w=W[i%W.length],p=Math.exp(-(Date.now()-t0)/1000/U.cfg.beat_decay);if((w.length+i++)%2==0&&Math.random()<p){const x=a.createOscillator(),e=a.createGain(),t=a.currentTime,f=50+(w.length*7+w.charCodeAt(0))%40;x.frequency.setValueAtTime(f*1.8,t);x.frequency.exponentialRampToValueAtTime(f,t+.12);e.gain.setValueAtTime(.3,t);e.gain.exponentialRampToValueAtTime(.001,t+.45);x.connect(e).connect(o);x.start(t);x.stop(t+.5)}},U.cfg.beat_ms);return R.stop}});
U.add('snd','combvoid',{sev:3.6,ax:{a:1},new:'comb-filter resonator: noise bursts ring in a feedback delay that keeps lengthening, so the room itself slows to a pulse and stops',play:(a,o,r)=>{const R=U.au.rig(a),d=a.createDelay(1),fb=a.createGain(),lp=a.createBiquadFilter(),g=a.createGain();let len=1/(120+r(300)*60);d.delayTime.value=len;fb.gain.value=.9;lp.type='lowpass';lp.frequency.value=1500;d.connect(lp).connect(fb).connect(d);lp.connect(g).connect(o);g.gain.value=.4;
 const burst=()=>{const s=a.createBufferSource(),e=a.createGain();s.buffer=U.au.noise(a,.05);e.gain.value=.06;s.connect(e).connect(d);s.start();len=Math.min(.45,len*1.25);d.delayTime.setTargetAtTime(len,a.currentTime,.5)};burst();R.iv(burst,3500);return()=>{R.stop();try{d.disconnect()}catch(e){}}}});
U.add('snd','lastbreath',{sev:3.32,ax:{a:.9},new:'breath synthesis from shaped noise: the gap between breaths keeps growing until the last long exhale',play:(a,o,r)=>{const R=U.au.rig(a),n=R.src(U.au.noise(a,2)),bp=a.createBiquadFilter(),lp=a.createBiquadFilter(),e=a.createGain();n.loop=true;bp.type='bandpass';bp.frequency.value=500;bp.Q.value=.8;lp.type='lowpass';lp.frequency.value=900;e.gain.value=0;n.connect(bp).connect(lp).connect(e).connect(o);n.start();let gap=U.cfg.breath_gap,dead=false;
 const breathe=()=>{if(dead)return;const t=a.currentTime,last=gap>U.cfg.breath_max;bp.frequency.setValueAtTime(400,t);bp.frequency.linearRampToValueAtTime(800,t+1.2);bp.frequency.linearRampToValueAtTime(350,t+(last?6:3));e.gain.setValueAtTime(0,t);e.gain.linearRampToValueAtTime(.35,t+1.2);e.gain.linearRampToValueAtTime(0,t+(last?6:3));if(last)return;gap+=U.cfg.breath_grow;R.to(breathe,(3+gap)*1000)};breathe();return()=>{dead=true;R.stop()}}});
U.add('snd','meltdown',{sev:3.18,ax:{a:.85},new:'a sound that dies while you read: pitch, brightness and level all melt to silence over about a minute',play:(a,o,r)=>{const R=U.au.rig(a),f=110+r(300)*40,lp=a.createBiquadFilter(),g=a.createGain(),t=a.currentTime,tc=U.cfg.melt_s/3;lp.type='lowpass';lp.frequency.setValueAtTime(1800,t);lp.frequency.setTargetAtTime(90,t,tc);g.gain.setValueAtTime(.25,t);g.gain.setTargetAtTime(0,t,tc);[1,1.25,1.5].forEach((m,i)=>{const x=R.osc('sawtooth',f*m);x.detune.value=(i-1)*7;x.frequency.setTargetAtTime(f*m*.25,t,tc);x.connect(lp);x.start()});lp.connect(g).connect(o);return R.stop}});
U.add('snd','wordghost',{sev:3.46,ax:{a:.95},new:'additive synthesis spelled by your word: one partial per letter, and the letters vanish one at a time',play:(a,o,r)=>{const R=U.au.rig(a);let live=[];const speak=w=>{live.forEach(x=>{try{x.stop()}catch(e){}});live=[];[...w.toLowerCase().replace(/[^a-z]/g,'').slice(0,8)].forEach((ch,i)=>{const x=a.createOscillator(),g=a.createGain(),t=a.currentTime;x.frequency.value=110*Math.pow(2,(ch.charCodeAt(0)-97)/12);x.detune.value=i*3;g.gain.setValueAtTime(.0001,t);g.gain.linearRampToValueAtTime(.06,t+1);g.gain.setTargetAtTime(0,t+U.cfg.ghost_s*(i+1),1.5);x.connect(g).connect(o);x.start(t);x.stop(t+U.cfg.ghost_s*(i+1)+9);live.push(x)})};
 speak(U.said[U.said.length-1]||U.you(r(300)));R.on(document,'change',e=>{const v=e.target&&e.target.value;if(v)speak(v)});return()=>{R.stop();live.forEach(x=>{try{x.stop()}catch(e){}})}}});
U.add('nav','adv_choicelog',{sev:3.83,ax:{x:0.082,n:0.908,v:0.986},desc:'your last choices are kept above the exits',new:'the last three exit labels the visitor chose are quoted above the exits as a record of consent',apply:c=>{if(!U.chose.length)return;const e=U.tag('small','display:block;opacity:.6;font:11px Courier New,monospace;margin-top:10px','recorded: '+U.chose.slice(-3).map(x=>'"'+x+'"').join(' then '));const x=c.w.querySelector('.exits');x&&x.before?x.before(e):c.w.append(e)}});
U.add('nav','consolevoice',{sev:3.32,ax:{n:.9,v:.9},new:'the devtools console becomes a channel: styled messages in your words and your history dumped as a table',desc:'the console is open (to me)',apply:c=>{const s='font:14px Courier New;color:#888',b='font:900 18px Arial Black;color:#f00';console.log('%c'+U.fill('You typed "{said}". I can read that from here too.',c),s);if(U.hist.length)console.table(U.hist.slice(-8).map(h=>({page:h.k,type:h.arch,title:h.t})));let i=0;U.live(c,()=>console.log('%c'+U.fill(U.pick(['{you}','page {k}: still here','I am logging you as "{you}"','the tab is yours. the page is not.','{said}'],c.r(310+i++)),c,i),i%3?s:b),U.cfg.console_ms)}});